pub fn recover_matrix<P: Preset>(
    partial_matrix: &[MatrixEntry<P>],
    backend: KzgBackend,
) -> Result<Vec<MatrixEntry<P>>> {
    let mut partial_matrix_map = BTreeMap::new();
    for matrix in partial_matrix {
        partial_matrix_map
            .entry(matrix.row_index)
            .or_insert(Vec::new())
            .push(matrix);
    }

    partial_matrix_map
        .into_par_iter()
        .map(|(_, entries)| {
